import React from 'react';
import { Bar } from 'react-chartjs-2';

function RiskBarChart({ risks }) {
  // Group scores by category
  const categoryScores = {};
  risks.forEach(r => {
    if (!categoryScores[r.category]) {
      categoryScores[r.category] = [];
    }
    categoryScores[r.category].push(Number(r.score));
  });

  // Calculate averages
  const categories = Object.keys(categoryScores);
  const averages = categories.map(cat => {
    const scores = categoryScores[cat];
    return scores.reduce((a, b) => a + b, 0) / scores.length;
  });

  const data = {
    labels: categories,
    datasets: [
      {
        label: 'Average Risk Score',
        data: averages,
        backgroundColor: '#60a5fa', // blue bars
      },
    ],
  };

  return (
    <div style={{ width: '600px', marginTop: '20px' }}>
      <h2>Average Risk Score by Category</h2>
      <Bar data={data} />
    </div>
  );
}

export default RiskBarChart;
